static const char* kCategoryLabels[KWS_CATEGORY_COUNT] = {
	"down", "go", "left", "no", "off", "on",
	"right", "stop", "up", "yes", "silence", "unknown"
};

static const uint32_t bram_addr_diag_inst_array[] = {
	0x200000B7U, 0x11111137U, 0x11110113U, 0x0020A023U,
	0x22222137U, 0x22210113U, 0x0020A223U, 0x33333137U,
	0x33310113U, 0x0020A823U, 0x200011B7U, 0x44444137U,
	0x44410113U, 0x0021A023U, 0x200401B7U, 0xFF018193U,
	0x55555137U, 0x55510113U, 0x0021A023U, 0x0000006FU,
};

enum ResultWord {
	kStatus = 0,
	kPredictedIndex = 1,
	kPredictedRawScore = 2,
	kOutputBase = 3,
};

enum StatusCode {
	kStatusStarted = 0x100,
	kStatusClearingOutputs = 0x101,
	kStatusBeforeModelRead = 0x102,
	kStatusModelBytesRead = 0x104,
	kStatusGetModelOk = 0x108,
	kStatusVersionRead = 0x10c,
	kStatusModelOk = 0x110,
	kStatusResolverOk = 0x120,
	kStatusInterpreterOk = 0x130,
	kStatusAllocating = 0x140,
	kStatusAllocateOk = 0x150,
	kStatusInputCopied = 0x160,
	kStatusInvoking = 0x170,
	kStatusInvokeOk = 0x180,
	kStatusSchemaMismatch = -1,
	kStatusAllocateFailed = -2,
	kStatusInputSizeMismatch = -3,
	kStatusInvokeFailed = -4,
	kStatusOk = 1,
};

static const char* KwsStatusName(int32_t status) {
	switch (status) {
	case kStatusStarted:
		return "started";
	case kStatusClearingOutputs:
		return "clearing outputs";
	case kStatusBeforeModelRead:
		return "before model read";
	case kStatusModelBytesRead:
		return "model bytes read";
	case kStatusGetModelOk:
		return "get model ok";
	case kStatusVersionRead:
		return "version read";
	case kStatusModelOk:
		return "model ok";
	case kStatusResolverOk:
		return "resolver ok";
	case kStatusInterpreterOk:
		return "interpreter ok";
	case kStatusAllocating:
		return "allocating tensors";
	case kStatusAllocateOk:
		return "allocate ok";
	case kStatusInputCopied:
		return "input copied";
	case kStatusInvoking:
		return "invoking";
	case kStatusInvokeOk:
		return "invoke ok";
	case kStatusSchemaMismatch:
		return "schema mismatch";
	case kStatusAllocateFailed:
		return "allocate failed";
	case kStatusInputSizeMismatch:
		return "input size mismatch";
	case kStatusInvokeFailed:
		return "invoke failed";
	case kStatusOk:
		return "ok";
	default:
		return "unknown";
	}
}

static void LoadWordsToBram(u32 base, const u32* data, size_t word_count,
							u32 word_offset) {
	for (size_t i = 0; i < word_count; ++i) {
		Xil_Out32(base + (word_offset + (u32)i) * WORD_SIZE_BYTES, data[i]);
	}
}

static void FlushBramWrites(void) {
	Xil_DCacheFlushRange(INST_BRAM_BASE, IMEM_BRAM_BYTES);
	Xil_DCacheFlushRange(DATA_BRAM_BASE, DMEM_BRAM_BYTES);
}

static void ClearMailbox(void) {
	for (u32 i = 0; i < DMEM_MAILBOX_BYTES / WORD_SIZE_BYTES; ++i) {
		Xil_Out32(DATA_BRAM_BASE + i * WORD_SIZE_BYTES, 0U);
	}
}

static void ResetGpioInit(void) {
	Xil_Out32(RESET_GPIO_BASE + GPIO_TRI_OFFSET, 0x0U);
}

static void SetRv32iReset(int assert_reset) {
	const u32 value = assert_reset ? 0x0U : 0x1U;
	Xil_Out32(RESET_GPIO_BASE + GPIO_DATA_OFFSET, value);
}

static int32_t ReadMailboxS32(u32 index) {
	const u32 addr = DATA_BRAM_BASE + index * WORD_SIZE_BYTES;
	Xil_DCacheInvalidateRange(addr, WORD_SIZE_BYTES);
	return (int32_t)Xil_In32(addr);
}

static u32 ReadDmemOffset(u32 byte_offset) {
	const u32 addr = DATA_BRAM_BASE + byte_offset;
	Xil_DCacheInvalidateRange(addr, WORD_SIZE_BYTES);
	return Xil_In32(addr);
}

static void WriteDmemOffset(u32 byte_offset, u32 value) {
	Xil_Out32(DATA_BRAM_BASE + byte_offset, value);
}

static void RunBramAddressDiagnostic(void) {
	static const u32 offsets_to_clear[] = {
		0x0000U, 0x0004U, 0x0008U, 0x0010U, 0x0040U,
		0x1000U, 0x4000U, 0x3FFC0U, 0x3FFF0U,
	};
	static const u32 offsets_to_dump[] = {
		0x0000U, 0x0004U, 0x0008U, 0x0010U, 0x0040U,
		0x1000U, 0x4000U, 0x3FFC0U, 0x3FFF0U,
	};

	xil_printf("BRAM address diagnostic mode\r\n");
	xil_printf("This test writes from RV32I to DMEM byte offsets 0x0, 0x4, "
			   "0x10, 0x1000, 0x3FFF0\r\n");

	ResetGpioInit();
	SetRv32iReset(1);

	for (size_t i = 0; i < sizeof(offsets_to_clear) / sizeof(offsets_to_clear[0]); ++i) {
		WriteDmemOffset(offsets_to_clear[i], 0U);
	}
	LoadWordsToBram(INST_BRAM_BASE, bram_addr_diag_inst_array,
					sizeof(bram_addr_diag_inst_array) /
						sizeof(bram_addr_diag_inst_array[0]),
					0U);
	FlushBramWrites();

	xil_printf("Diagnostic program loaded. Releasing RV32I reset.\r\n");
	SetRv32iReset(0);
	usleep(2000);
	SetRv32iReset(1);

	xil_printf("DMEM diagnostic readback:\r\n");
	for (size_t i = 0; i < sizeof(offsets_to_dump) / sizeof(offsets_to_dump[0]); ++i) {
		const u32 offset = offsets_to_dump[i];
		xil_printf("  DMEM+0x%05lx = 0x%08lx\r\n",
				   (unsigned long)offset,
				   (unsigned long)ReadDmemOffset(offset));
	}

	xil_printf("Expected if Port B uses byte address: "
			   "0x0000=11111111, 0x0004=22222222, 0x0010=33333333, "
			   "0x1000=44444444, 0x3FFF0=55555555\r\n");
	xil_printf("Expected if Port B uses word index but RTL drives byte address: "
			   "0x0000=11111111, 0x0010=22222222, 0x0040=33333333, "
			   "0x4000=44444444\r\n");
}

static void DumpOutputs(void) {
	const int32_t best_index = ReadMailboxS32(kPredictedIndex);
	const int32_t best_raw = ReadMailboxS32(kPredictedRawScore);

	xil_printf("KWS result index=%d raw=%d\r\n", (int)best_index,
			   (int)best_raw);
	if (best_index >= 0 && best_index < KWS_CATEGORY_COUNT) {
		xil_printf("KWS label=%s\r\n", kCategoryLabels[best_index]);
	}

	xil_printf("KWS outputs=[");
	for (int i = 0; i < KWS_CATEGORY_COUNT; ++i) {
		int32_t value = ReadMailboxS32(kOutputBase + (u32)i);
		xil_printf("%d%s", (int)value,
				   (i + 1 == KWS_CATEGORY_COUNT) ? "" : ",");
	}
	xil_printf("]\r\n");
}

int main(void) {
	init_platform();
	Xil_DCacheDisable();

	xil_printf("MLPerf Tiny KWS (DS-CNN) loader\r\n");
	xil_printf("IMEM base=0x%08lx DMEM base=0x%08lx\r\n",
			   (unsigned long)INST_BRAM_BASE,
			   (unsigned long)DATA_BRAM_BASE);

#if RUN_BRAM_ADDR_DIAG
	RunBramAddressDiagnostic();
	cleanup_platform();
	return 0;
#endif

	ClearMailbox();
	ResetGpioInit();
	SetRv32iReset(1);

	xil_printf("Loading IMEM (%lu words)\r\n",
			   (unsigned long)(sizeof(inst_array) / sizeof(inst_array[0])));
	LoadWordsToBram(INST_BRAM_BASE, inst_array,
					sizeof(inst_array) / sizeof(inst_array[0]), 0U);

	xil_printf("Loading DMEM (%lu words)\r\n",
			   (unsigned long)(sizeof(data_array) / sizeof(data_array[0])));
	LoadWordsToBram(DATA_BRAM_BASE, data_array,
					sizeof(data_array) / sizeof(data_array[0]),
					DMEM_IMAGE_OFFSET_WORDS);
	xil_printf("DMEM readback rodata[0]=0x%08lx model[0]=0x%08lx\r\n",
			   (unsigned long)Xil_In32(DATA_BRAM_BASE + 0x1000U),
			   (unsigned long)Xil_In32(DATA_BRAM_BASE + 0x1380U));

	FlushBramWrites();
	xil_printf("Memory load complete. Releasing RV32I reset.\r\n");
	SetRv32iReset(0);
	usleep(1000);

	xil_printf("Waiting for KWS status...\r\n");
	int32_t status = 0;
	int32_t last_status = -999;
	const u32 timeout_ms = 60000U;
	for (u32 i = 0; i < timeout_ms; ++i) {
		status = ReadMailboxS32(kStatus);
		if (status != last_status) {
			xil_printf("KWS status=%d (0x%08lx, %s)\r\n", (int)status,
					   (unsigned long)(u32)status, KwsStatusName(status));
			last_status = status;
		}
		if (status == kStatusOk || status < 0) {
			break;
		}
		usleep(1000);
	}

	if (status == kStatusOk) {
		xil_printf("KWS status OK\r\n");
		DumpOutputs();
	} else if (status < 0) {
		xil_printf("KWS error status=%d (%s)\r\n", (int)status,
				   KwsStatusName(status));
	} else {
		xil_printf("KWS timeout status=%d (%s)\r\n", (int)status,
				   KwsStatusName(status));
		xil_printf("KWS debug pred=%d raw=0x%08lx\r\n",
				   (int)ReadMailboxS32(kPredictedIndex),
				   (unsigned long)(u32)ReadMailboxS32(kPredictedRawScore));
	}

	cleanup_platform();
	return 0;
}
